/*
select dbo.GetViakElement('description', N'
<article><header><h1 viak="word">Port(англ:порт,отверстие,встраивать)
</h1></header><h3><a href="https://viakviak.livejournal.com/76661.html#method" target="_blank">Предположение</a></h3><span viak="summary">
Слово "Port"(англ:порт,отверстие,встраивать) - это калька со слова "приять" в смысле "принять"
</span><span viak="description">
Слово "Port"(англ:порт,отверстие,встраивать) - это калька со слова "ворота" при учете перехода "<a href="http://viakviak.livejournal.com/69930.html" target="_blank">П-В</a>"
</span></article>
', null);
*/
CREATE FUNCTION dbo.GetViakElement(
	@viakTag as varchar(64),
	@content as nvarchar(max),
	@default as nvarchar(255) = NULL
) returns nvarchar(max) as
	begin
	declare @value nvarchar(max) = cast(cast(@content as XML).query('//span[@viak=sql:variable("@viakTag")]') as nvarchar(max));
	if len(@value) = 0
		return @default;
	return @value;
	end
GO

IF OBJECT_ID('GetSummary') IS NOT NULL
	DROP FUNCTION dbo.GetSummary;
GO

CREATE FUNCTION dbo.GetSummary(
	@content as nvarchar(max),
	@default as nvarchar(255) = NULL,
  @isCapitalized as bit = 0
) returns nvarchar(255) as
	begin
	declare @summary nvarchar(255) = cast(@content as XML).query('//span[@viak="summary"]').value('.', 'nvarchar(255)');
	if len(@summary) = 0
		return @default;
	if ascii(@summary) = 10
		set @summary = trim(substring(@summary, 2, len(@summary) - 2));
	if substring(@summary, len(@summary), 1) = '.'
		set @summary = trim(substring(@summary, 1, len(@summary) - 1));
  if @isCapitalized = 1
    set @summary = '<b>' + substring(@summary, 1, 1) + '</b>' + substring(@summary, 2, len(@summary) - 1);
	return @summary;
	end
GO

/* Example:
	PRINT dbo.GetTabsHtml(1, N'765 Новые, 999999 Средние, 146191 Старые');
	PRINT dbo.GetTabsHtml(2, N'765 Новые, 999999 Средние, 146191 Старые');
*/
CREATE FUNCTION dbo.GetTabsHtml(
	@tabNumber int, -- active tab number
	@tabTitles nvarchar(1024) -- comma-delimited list of space-delimited pairs of "live journal numeric id" and "tab title"
) returns nvarchar(4000) as
	begin
	declare @html nvarchar(4000) = N'';
	declare @tabPair nvarchar(300);
	declare @tabLiveJournalId nvarchar(12);
	declare @tabTitle nvarchar(256);
	declare @tabCount int = 0;
	declare @tabPos int = 0;
	declare @linkFormat nvarchar(4000) = N'<a href="http://viakviak.livejournal.com/%s.html" target="_blank">%s</a>';
	declare @selectedFormat nvarchar(4000) = N'<b>%s</b>';
	declare dbCursor CURSOR FOR
		SELECT trim(value) as TabTitle FROM string_split(@tabTitles, ',');

	OPEN dbCursor;
	WHILE 1=1
		begin
		FETCH NEXT FROM dbCursor INTO @tabPair;
		if @@FETCH_STATUS < 0 break;
		set @tabCount = @tabCount + 1;

		set @tabPair = trim(@tabPair);
		set @tabPos = charindex(N' ', @tabPair);
		set @tabLiveJournalId = trim(substring(@tabPair, 1, @tabPos));
		set @tabTitle = trim(substring(@tabPair, @tabPos, len(@tabPair)));

		if len(@html) > 0
			set @html = @html + N' ...';
		if @tabNumber = @tabCount
			set @html = @html + formatmessage(@selectedFormat, @tabTitle);
		else
			set @html = @html + formatmessage(@linkFormat, @tabLiveJournalId, @tabTitle);

		end

	set @html = '<br/><small>...' + @html + '</small>';

	CLOSE dbCursor;
	DEALLOCATE dbCursor;
	return @html;
	end
GO

/* Example:
	PRINT dbo.GetNameHtml(N'527046 A, 1479720 C, 780346 D, 527264 G, 1479994 K, 1102529 N, 527436 S, 1480238 T, 527864 А, 1479042 В, 527934 Г, 1479209 Е, 528263 К, 1479603 Кр, 528472 М, 1480470 Н, 528727 П, 1480939 Пр, 529029 С, 1481097 См, 1102721 Т, 529350 У, 1481308 Ч', null);
*/
CREATE OR ALTER FUNCTION dbo.GetNameHtml(
	@tabLetters nvarchar(1024), -- comma-delimited list of space-delimited pairs of "live journal numeric id" and "tab letter"
  @tabNumber int = null
) returns nvarchar(4000) as
	begin
	declare @html nvarchar(4000) = N'';
	declare @tabPair nvarchar(300);
	declare @tabLiveJournalId nvarchar(12);
	declare @tabTitle nvarchar(256);
	declare @tabCount int = 0;
	declare @tabPos int = 0;
	declare @linkFormat nvarchar(4000) = N'<a href="http://viakviak.livejournal.com/%s.html" target="_blank">%s...</a>';
	declare dbCursor CURSOR FOR
		SELECT trim(value) as TabTitle FROM string_split(@tabLetters, ',');

	OPEN dbCursor;
	WHILE 1=1
		begin
		FETCH NEXT FROM dbCursor INTO @tabPair;
		if @@FETCH_STATUS < 0 break;
		set @tabCount = @tabCount + 1;

		set @tabPair = trim(@tabPair);
		set @tabPos = charindex(N' ', @tabPair);
		set @tabLiveJournalId = trim(substring(@tabPair, 1, @tabPos));
		set @tabTitle = trim(substring(@tabPair, @tabPos, len(@tabPair)));

		if len(@html) > 0
			set @html = @html + N' | ';
		set @html = @html + IIF(@tabNumber = @tabLiveJournalId, @tabTitle + '...', formatmessage(@linkFormat, @tabLiveJournalId, @tabTitle));

		end

	set @html = N'Словарик: ' + @html + '   <sub><i>' + cast(getdate() as varchar(20)) + '</i></sub><br/>';

	CLOSE dbCursor;
	DEALLOCATE dbCursor;
	return @html;
	end
GO

CREATE OR ALTER FUNCTION dbo.GetVocabulary(@tabNumber int) returns nvarchar(4000) as
	begin
	return dbo.GetNameHtml(N'527046 A, 1479720 C, 780346 D, 527264 G, 1479994 K, 1102529 N, 527436 S, 1480238 T, 527864 А, 1479042 В, 527934 Г, 1479209 Е, 528263 К, 1479603 Кр, 528472 М, 1480470 Н, 528727 П, 1480939 Пр, 529029 С, 1481097 См, 1102721 Т, 529350 У, 1481308 Ч', @tabNumber);
	end
GO

CREATE FUNCTION dbo.GetArticleUrl(
	@liveJournalId int
) returns nvarchar(300) as
	begin
	return formatmessage(N'http://viakviak.livejournal.com/%i.html', @liveJournalId);
	end
GO

CREATE FUNCTION dbo.GetLink(
	@liveJournalId int,
	@title as nvarchar(255)
) returns nvarchar(512) as
	begin
	set @title = trim(@title);
	return formatmessage(N'<a href="%s" target="_blank">%s</a>', dbo.GetArticleUrl(@liveJournalId), @title);
	end
GO

CREATE FUNCTION dbo.GetName(
	@title as nvarchar(255)
) returns nvarchar(512) as
	begin
	declare @posDelimiter as int = charindex(':', @title);
	declare @name as nvarchar(256) = trim(substring(@title, @posDelimiter + 1, len(@title) - @posDelimiter));
	declare @titleChar as nvarchar(1) = substring(@name, 1, 1);
	if @titleChar = '[' OR @titleChar = '"' OR @titleChar = '-'
		set @name = substring(@name, 2, len(@name) - 1);
	return @name;
	end
GO

CREATE PROCEDURE spAddItem
	@collectionID int, -- entity id of collection
	@itemID int, -- entity id of item
	@collectionTypeID int = NULL, -- optional entity id of the collection type
	@itemTypeID int = NULL, -- optional entity id of item type
	@orderIndex int = NULL -- optional order index of new item
AS
	begin
	SET NOCOUNT ON;

	DECLARE @orderIndexMax int = 0;
	DECLARE @listTypeID as int = 5;

	if @collectionTypeID IS NULL
		SELECT @collectionTypeID = TypeID FROM dbo.Entity WHERE EntityID = @collectionID;
	if @itemTypeID IS NULL
		SELECT @itemTypeID = TypeID FROM dbo.Entity WHERE EntityID = @itemID;
	if 1 = dbo.IsTypeOf(@collectionTypeID, @listTypeID)
		begin
		SELECT @orderIndexMax = MAX(OrderIndex) FROM dbo.CollectionItem WHERE CollectionID = @collectionID;
		if @orderIndex IS NULL OR @orderIndex < 0 OR @orderIndex > @orderIndexMax -- add..
			SET @orderIndex = @orderIndexMax;
		else -- reorder the end of the list..
			UPDATE dbo.CollectionItem SET OrderIndex = OrderIndex + 1 WHERE CollectionID = @collectionID AND OrderIndex > @orderIndex;
		end
	INSERT INTO dbo.CollectionItem(CollectionID, CollectionTypeID, ItemID, ItemTypeID, OrderIndex)
		VALUES(@collectionID, @collectionTypeID, @itemID, @itemTypeID, @orderIndex);
	return 0;
	end
GO

/*
	Adds translation of the same type as the specified existing item
	Returns Collection ID or negative incorrect argument number
*/
CREATE PROCEDURE spAddTranslation
	@translationOfID int,
	@translationLanguageID int,
	@translation nvarchar(max)
AS
	begin
	DECLARE @translationTypeID int = 4;
	DECLARE @itemTypeID int;
	DECLARE @collectionID int;
	DECLARE @newItemID int;

	SET NOCOUNT ON;

	if @translationOfID IS NULL OR @translationOfID <= 0
		return -1;
	if @translationLanguageID IS NULL OR @translationLanguageID <= 0
		return -2;
	if @translation IS NULL OR LEN(@translation) <= 0
		return -3;

	SELECT	@collectionID = CollectionID, @itemTypeID = ItemTypeID
	FROM	dbo.CollectionItem
	WHERE	ItemID = @translationOfID AND
			CollectionTypeID = @translationTypeID;

	if @itemTypeID IS NULL
		SELECT @itemTypeID = TypeID FROM dbo.Entity WHERE EntityID = @translationOfID;

	if @collectionID IS NULL
		begin
		INSERT INTO dbo.Entity(TypeID) VALUES(@translationTypeID);
		SET @collectionID = @@IDENTITY;

		exec spAddItem @collectionID, @translationOfID, @translationTypeID, @itemTypeID;
		end

	INSERT INTO dbo.Entity(TypeID, LanguageID, Translation) VALUES (@itemTypeID, @translationLanguageID, @translation);
	SET @newItemID = @@IDENTITY;

	exec spAddItem @collectionID, @newItemID, @translationTypeID, @itemTypeID;
	return @collectionID;
	end
GO

CREATE PROCEDURE spAddArticle
	@liveJournalID int,
	@title nvarchar(1024) = NULL,
	@labels nvarchar(2048) = NULL, -- comma separated labels
	@content nvarchar(max) = NULL
AS
begin
DECLARE @articleID int;
DECLARE @posStart int = 1;
DECLARE @posStop int = 0;
DECLARE @length int;
DECLARE @lbl nvarchar(128);
DECLARE @labelID int;
DECLARE @articleLabelTypeID int = 10001;
DECLARE @joinTypeID int = 6;
DECLARE @articleTypeID int = 101;
DECLARE @labelTypeID int = 102;
SET NOCOUNT ON;

SELECT @articleID = EntityID FROM dbo.Article WHERE LiveJournalID = @liveJournalID;
if @articleID IS NULL
	begin
	INSERT INTO dbo.Article(TypeID, LiveJournalID, Title, Content) VALUES (101, @liveJournalID, @title, @content);
	SET @articleID = @@IDENTITY;
	end
else if @content IS NOT NULL
	UPDATE dbo.Article SET Content = @content WHERE EntityID = @articleID;

if @labels IS NOT NULL
	begin -- labels..
	DELETE FROM dbo.ArticleLabel WHERE ArticleID = @articleID;

	SET @labels = LTRIM(RTRIM(@labels));
	SET @length = LEN(@labels);
	while @posStop < @length
		begin
		SET @posStop = CHARINDEX(N',', @labels, @posStart);
		if @posStop = 0 -- not found
			SET @posStop = @length + 1;-- end of line
		SET @lbl = LTRIM(RTRIM(SUBSTRING(@labels, @posStart, @posStop - @posStart)));
		if LEN(@lbl) > 0
			begin
			SELECT @labelID = EntityID FROM dbo.Label WHERE LabelName = @lbl;
			if @labelID IS NOT NULL
				begin
				INSERT INTO dbo.ArticleLabel(ArticleLabelTypeID, CollectionTypeID, ArticleTypeID, LabelTypeID, ArticleID, LabelID)
					VALUES (@articleLabelTypeID, @joinTypeID, @articleTypeID, @labelTypeID, @articleID, @labelID);
				end
			end
		SET @posStart = @posStop + 1;
		end
	end
end
GO

