CREATE OR ALTER PROCEDURE nav.GetArticlesByName (@titleFrom nvarchar(2), @titleStop nvarchar(2), @tabNumber int = null) as
	SELECT	NULL as EntityID, NULL as LiveJournalID, NULL as Title,
			NULL as Reference,
			NULL as [Url],
			dbo.GetVocabulary(@tabNumber) as SummaryReference,
			NULL as Summary,
			NULL as [Name]
	UNION ALL
	SELECT	EntityID, LiveJournalID, Title,
			dbo.GetLink(LiveJournalID, Title) as Reference,
			dbo.GetArticleUrl(LiveJournalID) as [Url],
			dbo.GetLink(LiveJournalID, dbo.GetSummary(Content, Title, 1)) as SummaryReference,
			dbo.GetSummary(Content, null, 0) as Summary,
			dbo.GetName(Title) as [Name]
	FROM	dbo.Article
	WHERE	@titleFrom <= dbo.GetName(Title) AND dbo.GetName(Title) < @titleStop AND SUBSTRING(Title, 1, 1) != '*'
	ORDER BY [Name]
GO

CREATE PROCEDURE nav.GetContent (@cutoffLineNumber int = 0, @tabNumber int, @liveJournalIdFrom int, @liveJournalIdTo int) as
	DECLARE @articleCount as int;
	declare @ArticlesRef as nvarchar(2048);
	declare @ArticlesByName as nvarchar(2048);

	begin try
		set @ArticlesRef = dbo.GetTabsHtml(@tabNumber, N'198084 2018/01, 146191 2019/10, 245954 2020/05, 399989 2020/10, 400272 2021/04, 480738 2021/08, 615576 2022/01, 713104 2022/05, 818458 2022/11, 952481 2023/04, 1102310 2023/11, 1255669 2024/03, 1344934 2024/09, 1396914 2025/01, 1481595 2025/11, 765 щас');
		set @ArticlesByName = dbo.GetVocabulary(@tabNumber);

		SELECT @articleCount = COUNT(*) FROM dbo.Article;

		SELECT -99 as LineNumber, 0 as LiveJournalID, N'Это интересно!' as Title, N'<b>Это интересно!</b><br/>' as Reference, '' as 'Url', '' as SummaryReference, '' as Summary
		UNION ALL
		SELECT	(-1) * cast(ROW_NUMBER() OVER (ORDER BY LiveJournalID DESC) as int) as LineNumber, LiveJournalID, Title,
				dbo.GetLink(LiveJournalID, Title) as Reference,
				dbo.GetArticleUrl(LiveJournalID) as 'Url',
				dbo.GetLink(LiveJournalID, dbo.GetSummary(Content, Title, 1)) as SummaryReference,
				dbo.GetSummary(a.Content, null, 0) as Summary
		FROM	dbo.Article a INNER JOIN
				dbo.ArticleLabel al ON al.ArticleID = a.EntityID INNER JOIN
				dbo.Label l ON l.EntityID = al.LabelID
		WHERE	l.LabelName IN (N'welcome')
		UNION ALL
		SELECT 0 as LineNumber, 0 as LiveJournalID, N'Статьи' as Title, @ArticlesRef as Reference, '' as 'Url', @ArticlesRef as SummaryReference, '' as Summary
		UNION ALL
		SELECT 0 as LineNumber, 0 as LiveJournalID, N'Статьи' as Title, @ArticlesByName as Reference, '' as 'Url', @ArticlesByName as SummaryReference, '' as Summary
		UNION ALL
		SELECT	cast(ROW_NUMBER() OVER (ORDER BY LiveJournalID DESC) as int) as LineNumber,
				LiveJournalID, Title,
				IIF(@cutoffLineNumber = ROW_NUMBER() OVER (ORDER BY LiveJournalID DESC), N'<lj-cut>', N'') +
					dbo.GetLink(LiveJournalID, Title) as Reference,
				dbo.GetArticleUrl(LiveJournalID) as 'Url',
				IIF(@cutoffLineNumber = ROW_NUMBER() OVER (ORDER BY LiveJournalID DESC), N'<lj-cut>', N'') +
					dbo.GetLink(LiveJournalID, dbo.GetSummary(Content, Title, 1)) as SummaryReference,
				dbo.GetSummary(Content, null, 0) as Summary
		FROM	dbo.Article a
		WHERE	@liveJournalIdFrom <= LiveJournalID AND LiveJournalID < @liveJournalIdTo
      AND substring(Title, 1, 1) != '*'
		UNION ALL
		SELECT cast((SELECT COUNT(*) FROM dbo.Article) + 1 as int) as LineNumber,
				0 as LiveJournalID, N'' as Title, N'</lj-cut>' as Reference, '' as 'Url', '</lj-cut>' as SummaryReference, '' as Summary
		WHERE	@cutoffLineNumber > 0 AND @articleCount >= @cutoffLineNumber
		ORDER BY LineNumber;
	end try
	begin catch
		PRINT 'nav.GetContent failed';
		SELECT	ERROR_NUMBER() AS ErrorNumber
				,ERROR_SEVERITY() AS ErrorSeverity
				,ERROR_STATE() AS ErrorState
				,ERROR_PROCEDURE() AS ErrorProcedure
				,ERROR_LINE() AS ErrorLine
				,ERROR_MESSAGE() AS ErrorMessage;
	end catch;
GO

