CREATE PROCEDURE nav.GetSpecialArticles as
	SELECT	a.LiveJournalID, a.Title,
			dbo.GetLink(a.LiveJournalID, a.Title) as Reference,
			dbo.GetArticleUrl(a.LiveJournalID) as 'Url',
