if OBJECT_ID('nav.RefCount') IS NOT NULL
	DROP PROCEDURE nav.RefCount;
GO

CREATE PROCEDURE nav.RefCount(@liveJournalId int) as
	declare @pattern as nvarchar(1024) = '%' + cast(@liveJournalId as nvarchar) + '.html"%';
	declare @title as nvarchar(1024);
	declare @count nvarchar(10);
	declare @tab nvarchar(1) = char(9);
	SET NOCOUNT ON;
	SELECT @title = Title from dbo.Article where LiveJournalID = @liveJournalId;
	SELECT @count = COUNT(*) FROM dbo.Article WHERE Content LIKE @pattern;
	PRINT cast(@liveJournalId as nvarchar(10)) + @tab + cast(@count as nvarchar(10)) + @tab + @title;
GO

if OBJECT_ID('nav.GetInvalidXmlArticles') IS NOT NULL
	DROP PROCEDURE nav.GetInvalidXmlArticles;
GO

CREATE PROCEDURE nav.GetInvalidXmlArticles as
	DECLARE @lineNumber int;
	declare @liveJournalID int;
	declare @title as nvarchar(256);
	declare @content as nvarchar(max);
	declare @summary as nvarchar(256);

	declare dbCursor CURSOR FOR
	SELECT	cast(ROW_NUMBER() OVER (ORDER BY LiveJournalID DESC) as int) as LineNumber,
			LiveJournalID, Title, a.Content as Content
	FROM	dbo.Article a
	OPEN dbCursor;
	WHILE 1=1
	begin
		FETCH NEXT FROM dbCursor INTO @lineNumber, @liveJournalID, @title, @content;
		if @@FETCH_STATUS < 0 break;
		begin try
			SET @summary = cast(@content as XML).query('//span[@viak="summary"]').value('.', 'nvarchar(255)');
			--PRINT cast(@lineNumber as nvarchar) + '. ' + cast(@liveJournalID as nvarchar) + '. ' + @title;
		end try
		begin catch
			PRINT '*** ' + cast(@lineNumber as nvarchar) + '. ' + cast(@liveJournalID as nvarchar) + '. ' + @title;
		end catch
	end
	CLOSE dbCursor;
	DEALLOCATE dbCursor;
GO

if OBJECT_ID('nav.FindArticles') IS NOT NULL
