GO

CREATE PROCEDURE nav.FindArticles(@findInContent nvarchar(1024)) as
	declare @pattern nvarchar(1024) = N'%' + @findInContent + N'%';
	SELECT	DISTINCT a.LiveJournalID, a.Title,
			dbo.GetLink(a.LiveJournalID, a.Title) as Reference,
			dbo.GetArticleUrl(a.LiveJournalID) as 'Url',
			dbo.GetLink(LiveJournalID, dbo.GetSummary(Content, Title, 1)) as SummaryReference,
			dbo.GetSummary(a.Content, null, 0) as Summary
	FROM	dbo.Article a INNER JOIN
			dbo.ArticleLabel al ON al.ArticleID = a.EntityID INNER JOIN
			dbo.Label l ON l.EntityID = al.LabelID
	WHERE	a.Content LIKE @pattern
	ORDER BY Title;
GO

