	WHERE	l.LabelName = @findLabel
	  AND	l2.LabelName = @findLabel2
	ORDER BY a.LiveJournalID desc;
GO

if OBJECT_ID('nav.GetRandom') IS NOT NULL
	DROP PROCEDURE nav.GetRandom;
GO

CREATE PROCEDURE nav.GetRandom as
  begin
  declare @minId int;
  declare @maxId int;
  declare @randomId int;
  SELECT @minId = MIN(EntityID) FROM dbo.Article;
  SELECT @maxId = MAX(EntityID) FROM dbo.Article;
  SET @randomId = @minId + FLOOR(RAND() * (@maxId - @minId)) + 1;
  declare @liveJournalId int;
  SELECT TOP 1 @liveJournalId = LiveJournalID FROM dbo.Article a WHERE EntityID >= @randomId ORDER BY EntityID;
  -- SELECT @minId as minId, @maxId as maxId, @randomId as randomId, @liveJournalId as liveJournalId
  exec nav.GetArticle @liveJournalId;
  end
GO

